    input  reset,
    output reg [4:0] q
);

    // Taps at positions 5 and 3 (1-based index)
    // In 0-based index, these are positions 4 and 2

    always @(posedge clk) begin
        if (reset) begin
            q <= 5'b10000; // active-high reset to 1
        end else begin
            // Compute next state based on Galois LFSR structure
            reg next_q;
            next_q = q[4] ^ q[2]; // XOR of tap positions 4 and 2

            // Shift right and insert next_q at the MSB
            q <= {next_q, q[4:1]};
        end
    end

