module TopModule (
    input  clk,
    input  reset,
    output q
);

    // Define the 5-bit register for the LFSR
    reg [4:0] lfsr;

    // Output the least significant bit as q
    assign q = lfsr[0];

    // LFSR logic
    always @(posedge clk) begin
        if (reset) begin
            // On reset, set the LFSR to 1 (active-high reset)
            lfsr <= 5'b00001;
        end else begin
            // Shift right and apply XOR for taps at positions 5 and 3
            // Note: In 5-bit LFSR, positions are 0 to 4, so tap positions 5 and 3
            // correspond to bit positions 4 and 2 (since 5-bit index is 0-4)
            // So, tap at position 4 (bit 4) and position 2 (bit 2)
            reg new_bit = lfsr[4] ^ lfsr[2];
            lfsr <= {lfsr[3:0], new_bit};
        end
    end

endmodule

module TopModule (
    input  c,
    input  d,
    output reg [3:0] mux_in
);

    // Implement the K-map using a 4-to-1 MUX with select lines a and b
    // The K-map is:
    // ab
    // cd  00  01  11  10
    // 00 | 0 | 0 | 0 | 1 |
    // 01 | 1 | 0 | 0 | 0 |
    // 11 | 1 | 0 | 1 | 1 |
    // 10 | 1 | 0 | 0 | 1 |

    // Map the K-map values to the MUX inputs
    // ab = 00 -> mux_in[0] = 0
    // ab = 01 -> mux_in[1] = 0
    // ab = 11 -> mux_in[2] = 1
    // ab = 10 -> mux_in[3] = 1

    // Determine the values for each MUX input based on c and d
    always @(*) begin
        mux_in[0] = 1'b0; // ab=00: 0
        mux_in[1] = 1'b0; // ab=01: 0
        mux_in[2] = (c & d); // ab=11: c & d
        mux_in[3] = (c & ~d); // ab=10: c & ~d
    end

endmodule

