module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output walk_left,
    output walk_right,
    output aaah
);

    // Define states
    typedef enum logic [1:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING
    } state_t;

    state_t current_state, next_state;

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        next_state = current_state;
        walk_left = 1'b0;
        walk_right = 1'b0;
        aaah = 1'b0;

        case (current_state)
            WALK_LEFT: begin
                if (!ground) begin
                    next_state = FALLING;
                    aaah = 1'b1;
                end else begin
                    walk_left = 1'b1;
                end
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    aaah = 1'b1;
                end else begin
                    walk_right = 1'b1;
                end
            end

            FALLING: begin
                if (ground) begin
                    // Resume walking in the previous direction
                    if (current_state == WALK_LEFT) begin
                        walk_left = 1'b1;
                    end else begin
                        walk_right = 1'b1;
                    end
                end else begin
                    // Still falling, no change in direction
                    aaah = 1'b1;
                end
            end
        endcase
    end

    // Bump handling logic
    always_comb begin
        if (current_state == FALLING) begin
            // Bumps during falling do not affect direction
            next_state = FALLING;
        end else begin
            if (bump_left) begin
                next_state = WALK_RIGHT;
            end else if (bump_right) begin
                next_state = WALK_LEFT;
            end
        end
    end

