module TopModule (
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);

typedef enum reg [2:0] {
    IDLE,
    SEARCH,
    START_SEQ,
    SHIFT_DELAY,
    COUNTING,
    WAIT_ACK
} state_t;

state_t state, next_state;

reg [3:0] delay;
reg [3:0] remaining;
reg [3:0] counter;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= IDLE;
        delay <= 4'b0000;
        remaining <= 4'b0000;
        counter <= 4'b0000;
        counting <= 1'b0;
        done <= 1'b0;
    end else begin
        state <= next_state;
        if (state == WAIT_ACK && ack) begin
            done <= 1'b0;
            counting <= 1'b0;
            remaining <= 4'b0000;
            counter <= 4'b0000;
        end
    end
end

always @(posedge clk) begin
    if (state == IDLE) begin
        next_state <= SEARCH;
    end else if (state == SEARCH) begin
        if (data == 4'b1101) begin
            next_state <= START_SEQ;
        end else begin
            next_state <= SEARCH;
        end
    end else if (state == START_SEQ) begin
        next_state <= SHIFT_DELAY;
    end else if (state == SHIFT_DELAY) begin
        if (counter < 4) begin
            delay[counter] <= data;
            counter <= counter + 1;
        end else begin
            next_state <= COUNTING;
        end
    end else if (state == COUNTING) begin
        if (remaining > 0) begin
            remaining <= remaining - 1;
            count <= remaining;
        end else begin
            next_state <= WAIT_ACK;
            done <= 1'b1;
        end
    end else if (state == WAIT_ACK) begin
        next_state <= IDLE;
    end
end

endmodule

