    reg [7:0] current_byte;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= S_IDLE;
            current_byte <= 8'b0;
            done <= 1'b0;
        end else begin
            current_byte <= in;
            case (current_state)
                S_IDLE: begin
                    if (in[3]) begin
                        next_state <= S_RECEIVING_BYTE1;
                    end else begin
                        next_state <= S_IDLE;
                    end
                end

                S_WAITING_FOR_START: begin
                    if (in[3]) begin
                        next_state <= S_RECEIVING_BYTE1;
                    end else begin
                        next_state <= S_WAITING_FOR_START;
                    end
                end

                S_RECEIVING_BYTE1: begin
                    next_state <= S_RECEIVING_BYTE2;
                end

                S_RECEIVING_BYTE2: begin
                    next_state <= S_RECEIVING_BYTE3;
                end

                S_RECEIVING_BYTE3: begin
                    next_state <= S_WAITING_FOR_START;
