    output reg counting,
    output reg done,
    input  ack
);

    // State definition
    typedef enum reg [2:0] {
        S_SEARCH,      // Searching for 1101
        S_RECEIVE,     // Receiving 4 bits for delay
        S_COUNTING,    // Counting down
        S_WAIT_ACK     // Waiting for ack
    } state_t;

    state_t state, next_state;

    // Delay value (4 bits)
    reg [3:0] delay;

    // Remaining count
    reg [3:0] remaining;

    // State machine logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S_SEARCH;
            counting <= 1'b0;
            done <= 1'b0;
            count <= 4'b0;
            delay <= 4'b0;
            remaining <= 4'b0;
        end else begin
            state <= next_state;
            if (state == S_WAIT_ACK && ack) begin
                counting <= 1'b0;
                done <= 1'b0;
                count <= 4'b0;
                remaining <= 4'b0;
                next_state <= S_SEARCH;
            end else if (state == S_COUNTING) begin
                if (remaining > 4'd0) begin
                    remaining <= remaining - 1;
                    count <= remaining;
                end else begin
                    done <= 1'b1;
                    next_state <= S_WAIT_ACK;
                end
            end else if (state == S_RECEIVE) begin
                // Shift in next bit
                if (remaining > 4'd0) begin
                    remaining <= remaining - 1;
                    count <= remaining;
                end else begin
                    done <= 1'b1;
                    next_state <= S_WAIT_ACK;
                end
            end else begin
                // Search for 1101
                if (data == 1'b1) begin
                    // Check if the current data matches the start sequence
                    if (data == 1'b1 && data == 1'b1 && data == 1'b0 && data == 1'b1) begin
                        next_state <= S_RECEIVE;
                        delay <= 4'b0;
                        remaining <= 4'b0;
                        counting <= 1'b1;
                    end
                end
            end
        end
    end

    // Output logic
    always @(posedge clk) begin
        if (state == S_RECEIVE) begin
            // Shift in the next 4 bits for delay
            if (data == 1'b1) begin
                delay <= {delay[2:0], 1'b1};
            end else begin
                delay <= {delay[2:0], 1'b0};
            end
            remaining <= delay;
            counting <= 1'b1;
            next_state <= S_COUNTING;
        end else if (state == S_COUNTING) begin
            if (remaining > 4'd0) begin
                remaining <= remaining - 1;
                count <= remaining;
            end else begin
                done <= 1'b1;
                next_state <= S_WAIT_ACK;
